% oqpskmod_NN.m
%
% Inputs:
%   Mod: OQPSK Modulation structure (generated by Initialize_Modulation_NN)
%   data: 1x(log2(Mod.M)*L) binary (0 and 1) input vector.
%
% Output:
%   y: Complex baseband OQPSK signal as a row vector.

function y = oqpskmod_NN(Mod, data)

%% 1. Get Modulation Parameters
% OQPSK是QPSK的一种，M固定为4
if Mod.M ~= 4
    error('OQPSK modulation order (M) must be 4.');
end

symbolmap = Mod.Txsymbolmap;
sps = Mod.sps;
M = Mod.M;
phaserot = Mod.phaserot;
h = Mod.PulseShaping.h;
ini_phase = Mod.ini_phase;
dfcTs = Mod.dfcTs;
delay = Mod.PulseShaping.delay;
half_symbol = Mod.PulseShaping.half_symbol; % OQPSK的关键参数

%% 2. Symbol Mapping (将比特流转换为符号索引)
% 将比特流每2个一组进行分组
bits_per_symbol = log2(M); % 结果是 2
data_matrix = vec2mat(data, bits_per_symbol);

% 将二进制转换为十进制 (0, 1, 2, 3)
decimal_symbols = bi2de(data_matrix, 'left-msb');

% 应用格雷码映射 (如果需要)
v = symbolmap(decimal_symbols + 1);

%% 3. OQPSK Modulation (核心修改部分)
% 与QPSK不同，OQPSK需要分别处理I路和Q路
% 标准的OQPSK/QPSK星座点 (未经旋转)
% 符号 0 (00) -> I=1, Q=1
% 符号 1 (01) -> I=-1, Q=1
% 符号 2 (11) -> I=-1, Q=-1
% 符号 3 (10) -> I=1, Q=-1
% (注意：这是格雷码映射后的顺序，符号2和3与二进制顺序不同)
constellation = [1+1i, -1+1i, -1-1i, 1-1i] / sqrt(2); % 归一化功率

% 将符号索引映射到复数星座点
S_complex = constellation(v + 1);

% 分离I路和Q路符号
I_symbols = real(S_complex);
Q_symbols = imag(S_complex);

% 上采样I路和Q路
I_upsampled = upsample(I_symbols, sps);
Q_upsampled = upsample(Q_symbols, sps);

% 对Q路信号施加半个符号周期的延迟
% 创建一个半符号周期的延迟滤波器
delay_filter = [zeros(1, half_symbol), 1];
Q_delayed_upsampled = conv(Q_upsampled, delay_filter, 'same'); % 'same' 保持长度不变

% 合并I路和延迟后的Q路
S_offset = I_upsampled + 1i * Q_delayed_upsampled;

%% 4. Pulse Shaping
% 对合并后的偏移信号进行脉冲成形
x = conv(S_offset, h);

% 截取有效部分，需要考虑滤波器延迟和我们手动加入的半符号延迟
% 由于Q路被延迟了，总的有效信号长度也需要考虑这点
% 这里的对齐可能需要微调，但通常的截取方式是：
x = x(delay + 1 : end - delay);


%% 5. Apply phase rotation, frequency and phase offset
% 对OQPSK信号施加旋转。注意：旋转是在I/Q合并后进行的
rotated_x = x * exp(1i * phaserot);

% 施加频率和初始相位偏移
y = complex(rotated_x .* exp(1i*2*pi*dfcTs/sps*(0:numel(rotated_x)-1) + 1i*ini_phase));

end
